import os
import six
import base64
import logging
import platform
import psutil
import inspect
import re

from subprocess import check_output
from importlib.metadata import distributions, version, PackageNotFoundError
from packaging.version import Version, InvalidVersion

from .exception import AdminApiProcedureFailureException

from ipaddress import IPv4Address, IPv6Address, AddressValueError

installed = [pkg.metadata['Name'].lower() for pkg in distributions()]
if "taf.internal.node" in installed:
    import taf.internal.node


def enable_logging(log_level=logging.INFO, handler=None):
    """Enable ute_common_admin logging with AdminApiLogger."""
    logger = logging.getLogger("AdminApiLogger")
    logger.addHandler(handler or logging.StreamHandler())
    logger.setLevel(log_level)


def ensure_parent_dir_exists(file):
    """Ensure directory exists."""
    parent_dir = os.path.dirname(file)
    if parent_dir and not os.path.exists(parent_dir):
        os.makedirs(parent_dir)


def running_on_windows():
    """Check if script is running on Windows OS."""
    return platform.system().lower() == 'windows'


def base64encode(data):
    """Python 2/3 base64 encoding."""
    if six.PY3 and isinstance(data, str):
        input_bytes = data.encode('utf8')
    else:
        input_bytes = data

    b64data = base64.urlsafe_b64encode(input_bytes)
    if six.PY3:
        return b64data.decode('ascii')
    return b64data


def check_ip_address_format(host):  # noqa: C901
    """Check if IP address has correct format."""

    if host[0] == "[":
        host = host[1:]
    if host[-1] == "]":
        host = host[:-1]

    try:
        IPv4Address(host)
        return host
    except AddressValueError:
        try:
            IPv6Address(host)
            host = "[" + host + "]"
            return host
        except Exception as my_error:
            raise AddressValueError(str(my_error) + "," + host + ' is not a valid IP. ')


def get_node_process_counter():
    """returns the num of open processes"""
    counter = 0
    for process in psutil.pids():
        try:
            p = psutil.Process(process)
            if p.name() == 'node':
                counter += 1
        except psutil.NoSuchProcess:
            pass
    return counter


def fail_if_resp_contains_fail(response):
    """fails keyword when response contains fail"""
    if "fail" in response.lower():
        raise AdminApiProcedureFailureException("""Response contains fail.
            Status reached: {}""".format(response))


def get_memory_usage():
    """gets memory usage"""
    try:
        return psutil.virtual_memory()
    except Exception as e:
        return str(e)


def create_empty_text_files(file_list):
    """creates empty text files"""
    for f in file_list:
        ensure_parent_dir_exists(f)
        open(f, "w").close()


def get_node_path():
    """Gets node path"""
    node_dir = ""
    try:
        node_dir = os.path.dirname(inspect.getfile(taf.internal.node))
    except Exception:
        pass

    if running_on_windows():
        nodejs_bin = try_node(["node.exe", os.path.join(node_dir, "resources", "windows", "bin", "node.exe")])
    else:
        nodejs_bin = try_node(["node", os.path.join(node_dir, "resources", "linux", "bin", "node")])

    return nodejs_bin


def try_node(paths):
    """Tries executing node process"""

    for path in paths:
        try:
            node_version = check_output([path, "--version"])
            if node_version_is_ok(node_version):
                return path
        except Exception:
            pass

    return None


def node_version_is_ok(node_version):
    """Checks if node version meets requirements"""

    node_version = re.sub(b"[a-zA-Z]+", b"", node_version).rstrip()
    try:
        return Version(node_version.decode("utf-8")) >= Version("12.13.0")
    except InvalidVersion:
        return "Invalid version format"


def get_library_version(library):
    """Returns library version"""

    try:
        return version(library)
    except PackageNotFoundError:
        return "not_installed"


def get_port_usage(port):
    """Gets netstat output for given port number"""
    try:
        netstat_output = check_output(["netstat", "-tupena"])
        header = netstat_output.splitlines()[:2]
        header_decoded = [line.decode() for line in header]
        usage = [line for line in netstat_output.splitlines() if str(port).encode() in line]
        usage_decoded = [line.decode() for line in usage]
        return "\n".join(header_decoded + usage_decoded)
    except Exception:
        return ["netstat not found"]
